:TE'NAD+AE+12247970000Z++EDI DEMONSTRATION SYSTEM SG'NAD+AH+10005470000Z++COLD STORAGE SINGAPORE (1983) PTE L:TD+SINGAPORE SINGAPORE'NAD+CG+11306920000Z++AB SHIPPING PTE LTD'NAD+CA+11306920000Z++AB SHIPPING PTE LTD'NAD+BB'RFF+DAN:D'UNS+D'CST+1+95030091'FTX+AAA+++TOY TYPEWRITERS'LOC+27+CN'MEA+AAF++NMB:100.0000'MOA+63:225900.00'CST+2+95030092'FTX+AAA+++SKIPPING ROPES'LOC+27+CN'MEA+AAF++NMB:550.0000'MOA+63:49950.00'UNS+S'CNT+5:2'CNT+6:1'CNT+22:1'TAX+1'MOA+63:275850.00'UNT+69+CWISEB00002114'";
			var cuspmt = new Cuspmt09b();
			cuspmt.Parse(new UNOASGCharacterSet(), message);
			AssertEquals("Handling Agent Details split into specific line fields for TN41", "", cuspmt.HandlingAgent);
