		public void TestCAPermitConditions()
		{
			AssertEquals("80 Character condition line chunks", 4, CusPMT4Test5.CAPermitConditions.Length);
			AssertEquals("CA condition 1: 1st 80 char chunk", "<b><ExpandToFit>Y96 </b> - APPLICATION IS APPROVED ON CONDITION THAT DECLARANT/ EXPORTER HAS        ", CusPMT4Test5.CAPermitConditions[0].Condition);
			AssertEquals("CA condition 1: 2nd 80 char chunk", "EXERCISED DUE DILIGENCE TO DETERMINE THAT THE GOODS ARE NOT CONTROLLED UNDER    ", CusPMT4Test5.CAPermitConditions[1].Condition);
			AssertEquals("CA condition 1: 3rd 80 char chunk", "STRATEGIC GOODS (CONTROL) ACT & A STRATEGIC GOODS PERMIT IS NOT REQUIRED.       ", CusPMT4Test5.CAPermitConditions[2].Condition);
			AssertEquals("CA condition 1: 4th 80 char chunk", "FOR ALL ITEMS.", CusPMT4Test5.CAPermitConditions[3].Condition);
		}

		public void TestCustomsPermitConditions()
		{
			AssertEquals("80 Character condition line chunks", 18, CusPMT4Test5.CustomsPermitConditions.Length);
			AssertEquals("Customs condition 1:", "<b><ExpandToFit>Y99 </b> - SPECIMEN PERMIT ONLY", CusPMT4Test5.CustomsPermitConditions[0].Condition);
			AssertEquals("Customs condition 2:", "<b><ExpandToFit>Z01 </b> - APPROVED BY SINGAPORE CUSTOMS.", CusPMT4Test5.CustomsPermitConditions[1].Condition);
			AssertEquals("Customs condition 3: 1st 80 char chunk", "<b><ExpandToFit>GA  </b> - APPROVED BY CUSTOMS SUBJECT TO THE DECLARANT COMPLYING WITH THE FOLLOWING", CusPMT4Test5.CustomsPermitConditions[2].Condition);
			AssertEquals("Customs condition 3: 2nd 80 char chunk", "CONDITION(S) FOR THE PERMIT TO BE VALID. FAILURE TO COMPLY WITH THE CONDITION(S)", CusPMT4Test5.CustomsPermitConditions[3].Condition);
			AssertEquals("Customs condition 3: 3rd 80 char chunk", "IS AN OFFENCE.", CusPMT4Test5.CustomsPermitConditions[4].Condition);
			AssertEquals("Customs condition 4: 1st 80 char chunk", "<b><ExpandToFit>P1  </b> - THE CONTAINER(S) MUST BE PRODUCED AT CUSTOMS CHECKPOINT(S) FOR CLEARANCE ", CusPMT4Test5.CustomsPermitConditions[5].Condition);
			AssertEquals("Customs condition 4: 2nd 80 char chunk", "UNLESS DIRECTED TO 'GREEN' LANE. FOR CONTAINER(S) TO BE SCANNED, PLEASE PRODUCE ", CusPMT4Test5.CustomsPermitConditions[6].Condition);
			AssertEquals("Customs condition 4: 3rd 80 char chunk", "FOR SCANNING BY ICA AT SCANNING STATION AS DIRECTED.", CusPMT4Test5.CustomsPermitConditions[7].Condition);
			AssertEquals("Customs condition 5: 1st 80 char chunk", "<b><ExpandToFit>D6  </b> - AN E-FILE APPLICATION MUST BE MADE TO COMPANY COMPLIANCE BRANCH FOR      ", CusPMT4Test5.CustomsPermitConditions[8].Condition);
			AssertEquals("Customs condition 5: 2nd 80 char chunk", "SUPERVISION OF STUFFING/UNSTUFFING OF CONTAINER. SELECT APPLICATION FOR         ", CusPMT4Test5.CustomsPermitConditions[9].Condition);
			AssertEquals("Customs condition 5: 3rd 80 char chunk", "SUPERVISION UNDER TEMPORARY IMPORT (PERMITS OR CARNETS)                         ", CusPMT4Test5.CustomsPermitConditions[10].Condition);
			AssertEquals("Customs condition 5: 4th 80 char chunk", "(WEBSITE:HTTP://WWW.CUSTOMS.GOV.SG).", CusPMT4Test5.CustomsPermitConditions[11].Condition);
			AssertEquals("Customs condition 6: 1st 80 char chunk", "<b><ExpandToFit>AY  </b> - GOODS NOT EXPORTED/TRANSHIPPED OR BONDED IN A BONDED/LICENSED WAREHOUSE  ", CusPMT4Test5.CustomsPermitConditions[12].Condition);
			AssertEquals("Customs condition 6: 2nd 80 char chunk", "OR RECEIVED BY THE CLAIMANT ON THE SAME DAY OF REMOVAL MUST BE STORED AT A PLACE", CusPMT4Test5.CustomsPermitConditions[13].Condition);
			AssertEquals("Customs condition 6: 3rd 80 char chunk", "APPROVED BY A PROPER OFFICER OF CUSTOMS.", CusPMT4Test5.CustomsPermitConditions[14].Condition);
			AssertEquals("Customs condition 7: 1st 80 char chunk", "<b><ExpandToFit>A6  </b> - IF THE PERMIT IS NOT USED, IT MUST BE CANCELLED OR RE-VALIDATED NOT LATER", CusPMT4Test5.CustomsPermitConditions[15].Condition);
			AssertEquals("Customs condition 7: 2nd 80 char chunk", "THAN 24 HOURS OF ITS EXPIRY.", CusPMT4Test5.CustomsPermitConditions[16].Condition);
			AssertEquals("Customs condition 8", "<b><ExpandToFit>EEE </b> - END OF CARGO CLEARANCE PERMIT.", CusPMT4Test5.CustomsPermitConditions[17].Condition);
		}

